function beginSkyScene(initialDocument=false){
  if(!initialDocument)_skyInitialDocument=false;
  window.SalahMoonRuntime?.invalidate("native beginSkyScene",{initialDocument:initialDocument&&_skyInitialDocument&&_runtimeGeneration===0});
  const c=$(".c"); if(c){ c.classList.add("sky-pending","sky-initializing"); c.classList.remove("moon-ready"); }
  _skySceneKey=null; _skyCommitted=false; _skyMoonPresence=0; _starsProjected=false;
  _cloudReady=false; cloudState.covLow=cloudState.covMid=cloudState.covHigh=0;
  _cloudDirty=true; if(_colDens) _colDens.fill(0);
  if(_cloudCtx&&_cloudCv) _cloudCtx.clearRect(0,0,_cloudCv.width,_cloudCv.height);
  updateSkySurface();

function paintCelestialWithoutTimetable(){
  const identity=skySceneIdentity(),sun=window.SalahNativeSkyHost?.cloudLighting?.()?.sun;
  if(identity===null||!Number.isFinite(sun?.altDeg))return;
  if(identity!==_skySceneKey){beginSkyScene(_skyInitialDocument);_skySceneKey=identity;}
  const n=nowParts();if(moonGeometryObservation({nowMin:n.h*60+n.mi+n.s/60}).fresh!==true)renderMoon();
  projectStars(simDate());
  const a=lunarPresentation(sun.altDeg),c=$(".c");
  c.style.setProperty("--moonfeat","1");c.style.setProperty("--moonocc","1");
  c.style.setProperty("--moongrp",a.moonShow.toFixed(3));c.style.setProperty("--moonbeam",(0.6*a.moonlight).toFixed(3));
  _skyMoonPresence=a.moonShow;window.SalahMoonRuntime?.request();updateSkySurface();
  // Publish the native body and matching real catalogue in this synchronous
  // turn. No prayer surrogate, sleep, fade or whole-card loading gate.
  c.classList.remove("sky-pending");
  // Preserve the existing first-theme transition suppression until paint(A)
  // installs its complete palette; pending prayer data must not cause a fade.
}

{ const e=A.solarElevationDeg, noon=clamp(e/40), sunAmt=clamp((e+1.5)/7), sunLow=1-clamp(e/5.5);
  // NUCLEUS + BODY colour are tone-mapped in atmosphere() (Kasten–Young airmass + Beer–Lambert
  // + CCT colour response → ACES); actual cloud alpha obstructs the light group once.
  // (a defined warm body with atmosphere-dependent colour; painted clouds may obstruct it completely).
  c.style.setProperty("--sunamt",sunAmt.toFixed(3));                            // PRESENCE only (is the sun up?) — NOT a brightness mute
  c.style.setProperty("--sunbodyamt",clamp((e+1.5)/1.5).toFixed(3));              // radiant low-sun body only; zero at the existing -1.5° cutoff
  c.style.setProperty("--sunlow",sunLow.toFixed(3));                            // retained low-elevation diagnostic; no body-size or two-layer handoff authority
  c.style.setProperty("--suncore",A.sunCoreRGB);                               // tone-mapped NUCLEUS colour (from atmosphere)
  c.style.setProperty("--sunmid",A.sunMidRGB);                                 // modest limb radiance falloff of the SAME attenuated spectrum
  if(e<40&&A.sunProfile)c.style.setProperty("--sunprofile","radial-gradient(circle closest-side,"+A.sunProfile.map(p=>p.colour+" "+(p.radius*100)+"%").join(",")+",transparent 100%)");
  else c.style.removeProperty("--sunprofile");                                // byte-identical established high-Sun gradient
  c.style.setProperty("--sundisc",(1.10-0.24*noon).toFixed(3));                 // enlarged presentation body: horizon presence/clipping must not shrink it into a button; high-Sun footprint unchanged
  // The low-left nucleus belongs to the visible arc horizon, not the old fixed 216px layout.
  // Read its existing geometry only below apex; noon placement remains unchanged.
  let sunHorizonPx=216;
  if(noon<1){ const hz=$(".arc .horizon"), atmo=$(".atmo");
    if(hz&&atmo){ const hr=hz.getBoundingClientRect(), ar=atmo.getBoundingClientRect();
      if(hr.width>0&&Number.isFinite(hr.top-ar.top))sunHorizonPx=hr.top-ar.top; } }
  const sunLiftPx=40+(sunHorizonPx-40)*(1-noon), sunX2Px=20;   // on-card core, low at contact → existing top-left apex
  c.style.setProperty("--sunlift",sunLiftPx.toFixed(1)+"px");
  c.style.setProperty("--sunx2",sunX2Px.toFixed(1)+"px");
  // VISIBLE-SUN screen coordinate (the corner-sun disc centre). The DISCRETE solar optics (22° halo, sundogs,
  // pillar, sun bloom, crepuscular rays, cloud sun-haze) register HERE — to the body the eye actually sees —
  // NOT to the arc-sun azimuth (--sunx/--suny), which sweeps mid-card and left the halo detached center-screen
  // (an instant FAIL). The diffuse HORIZON scatter band and the anti-solar Belt/anticrepuscular rays stay on the
  // azimuth (--sunx / --antix), which is physically where they belong. See DESIGN.md › "Sun layers".
  c.style.setProperty("--sunvx",(sunX2Px/325*100).toFixed(1)+"%");
  c.style.setProperty("--sunvy",(sunLiftPx/530*100).toFixed(1)+"%");
  c.style.setProperty("--sunray",((0.10+0.30*clamp(e/30))*A.sunCloudT).toFixed(3));  // rays fade via TRANSMITTANCE (cloud transmittance from atmosphere), not a grey mix
  c.style.setProperty("--sunpulse",(_REDUCED?1:1+(0.045+0.035*A.heat)*Math.sin(simNow()/1000/23)+0.015*Math.sin(simNow()/1000/6.5)+(1-noon)*0.16).toFixed(4));  // slow coronal breathing + a faint faster ray flicker + broader corona at low sun (all simTime-driven)
  c.style.setProperty("--sunflat",(1-0.20*clamp((4-e)/8)*clamp((e+3)/4)).toFixed(3));   // atmospheric REFRACTION oblateness (~0.8 at the horizon, 1 above ~5°)
}

function render(){
  if(!simulationReady()){ withdrawPrayerPresentation();paintWeatherHeader(weatherHeader(weatherDecision(),false));renderCalendarDates(selectCalendarDisplay(null));return; }
  setLocLabel();                                              // keep the header location label in sync with runtime config (local mode / settings panel)
  syncWeather();                                              // sim/fast-forward: pull weather from the forecast track at simTime
  const M=model();
  if(!M){
    withdrawPrayerPresentation();const d=weatherDecision();paintWeatherHeader(weatherHeader(d,d.record?.isDay!==0));
    // No accepted scene paint may leave another epoch's particles behind. The
    // independently admitted header remains usable while the timetable loads.
    $(".c").dataset.fx=d.record?wxClass(d.renderCode):"unavailable";$(".c").dataset.lightning="off";$(".c").dataset.precip="off";$(".c").style.setProperty("--rain-op","0");
    paintCelestialWithoutTimetable();renderCalendarDates(selectCalendarDisplay(null));return;
